  if(i.kind==='stash'){clearNotice('search');if(state.backpack.searched.includes(i.item.id)){openPack(i.item);return;}if(reload>0||healing)return;searchAction={container:i.item,time:0,x:state.x,z:state.z};releaseCombat();hearNoise(actors.enemies,state.x,state.z,9);sound.play('reload',.14,.75);return;}
