  if(i.kind==='weapon'){if(reload>0){notify('Finish reloading before recovering a weapon.',1.5);return;}const receipt=recoverWeapon(state,i.item);if(!receipt){notify(weaponProfile({weapon:i.item.weapon}).kind==='melee'?'Already carried. Choose it from the weapon rack.':'Ammunition reserve full. This weapon stays here.',2);return;}const discovered=receipt.id.startsWith('weapon-');if(discovered)selectWeapon(i.item.weapon);cacheVisuals.find(c=>c.id===i.item.id).mesh.visible=false;fieldUI.receipt([receipt],discovered?'Weapon recovered':'Spare ammunition');sound.play('collect');save();updateHUD();return;}
