  if(i.kind==='supply'){if(i.item.type==='ammo'){const recovered=supplyAmmo(state);if(!recovered.length){notify('Ammunition reserves are full. This cache stays here.');return;}fieldUI.receipt(recovered,'Ammunition recovered');}else{if(state.medkits>=20){notify('Medical belt is full. This dressing stays here.');return;}state.medkits++;fieldUI.receipt([{id:'dressing',count:1}],'Medical belt');}state.collected.push(i.item.id);supplyVisuals.find(s=>s.id===i.item.id).mesh.visible=false;sound.play('collect');save();updateHUD();return;}
  if(i.kind==='vehicle'){const index=actors.vehicles.indexOf(i.item);if(coop?.remote?.vehicle===index||coop?.reservedVehicle===index){notify('Your partner is driving this truck. The other truck is free.');return;}if(coop?.guest){coop.claimVehicle(index);notify('Checking the truck seat…',1);return;}resetTravel();vehicle=i.item;state.y=groundHeight(vehicle.x,vehicle.z);state.yaw=vehicle.angle;notify('W / S drive · A / D steer · Space brake · E leave',5);}
